  const p = hundredths(value) * hundredths(pct) * BigInt(times); // in 1/10000 of a hundredth
  const a = p < 0n ? -p : p;
  const q = a / 10000n;
  const rem = a % 10000n;
  const r = rem > 5000n || (rem === 5000n && (halfUp || q % 2n === 1n)) ? q + 1n : q;
  return p < 0n ? -r : r;
}

/** A claim's due: the figure fixed when it was settled, otherwise the one its person's last statement bound it to (never while PENDING),
 *  otherwise its amount at the rate in force on its date. Given the sheet's late charge, an overdue claim's figure gains,
 *  for every full 30 days overdue, the late percent in force on that boundary (its due-by plus 30, 60, 90 ... days) of
 *  it plus the charges of the boundaries before it (compounding), each rounded like the claim and added up (never bound by a statement; frozen in when settled). Last, the live
 *  due is at least the sheet's floor in force on its date (a correction has no floor). Both round by the sheet's
 *  policy date (see Late). */
export function claimDue(claim: Claim, rate: string | undefined, floor: Dated, late?: Late): string {
  if (claim.due !== null) return claim.due;
  const halfUp = roundsHalfUp(claim, late);
  const figure = claim.stated && claim.status !== 'PENDING' ? (claim.statedDue ?? 'n/a') : due(claim.amount, rate, halfUp);
  if (figure === 'n/a') return figure;
  const boundaries = late === undefined ? [] : lateBoundaries(claim, late);
  const charged = boundaries.reduce((t, b) => t + percentOf(shown(t), late!.pct(b), 1, halfUp), hundredths(figure));
  const f = hundredths(floor(claim.date));
  return shown(charged < f && hundredths(claim.amount) >= 0n ? f : charged);
}

/** The sum of a person's figures: the figures of their claims that count (each at the rate, of the grade in force,
 *  on its date, with its late charge) added up; 'n/a' when their grade has no rate today and none of those claims has
 *  a figure. */
function personFigures(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated): string {
  const counted = claims.filter(counts);
  const figures = counted.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late));
  if (rateFor(rates, gradeOn(person, late.today), late.today) === undefined && figures.every((f) => f === 'n/a')) return 'n/a';
  return sum(figures);
}

/** A person's settled-total and open-total: the figures (see personFigures) of their SETTLED claims that count
 *  (frozen when settled, corrections included), and of their OPEN and PENDING ones, each added up, skipping n/a.
 *  Together they make the sum of their figures, before the cap. */
export function personSplit(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated): { settled: string; open: string } {
  const figure = (c: Claim) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late);
  const counted = claims.filter(counts);
  return {
    settled: sum(counted.filter((c) => c.status === 'SETTLED').map(figure)),
    open: sum(counted.filter((c) => c.status !== 'SETTLED').map(figure)),
  };
}

/** A person's due-total: the sum of their figures (see personFigures), at most the sheet's cap (null: none); 'n/a'
 *  is not capped. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap) ? shown(hundredths(cap)) : total;
}

/** A person's excess: how far the sum of their figures is above the sheet's cap; 0.00 when it is not (or with no
 *  cap, or an n/a due-total). */
export function personExcess(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap)
    ? shown(hundredths(total) - hundredths(cap))
    : '0.00';
}

/** A candidate rate: a percent 0.00 or more with up to two decimals (as the rate form takes it). */
export const RATE_PATTERN = /^\d{1,5}(\.\d{1,2})?$/;

/** What a candidate rate would change if it applied to the grade on every date: of the OPEN and PENDING claims whose
 *  person is on the grade on the claim's date, how many would show a different due, and the sum of the differences
 *  (new due minus current due; an n/a due counts as 0.00). A claim bound by a statement keeps its due, so never
 *  changes; settled claims are not looked at. */
export function ratePreview(
  claims: Claim[],
  people: Person[],
  rates: Rate[] | undefined,
  grade: string,
  pct: string,
  late: Late,
  floor: Dated,
): { count: number; diff: string } {
  const byId = new Map(people.map((p) => [p.id, p]));
  const value = (d: string) => (d === 'n/a' ? 0n : hundredths(d));
  let count = 0;
  let diff = 0n;
  for (const c of claims) {
    const person = byId.get(c.personId);
    if (!isOpen(c) || person === undefined || gradeOn(person, c.date) !== grade) continue;
    const now = claimDue(c, rateFor(rates, grade, c.date), floor, late);
    const then = claimDue(c, pct, floor, late);
    if (now === then) continue;
    count++;
    diff += value(then) - value(now);
  }
  return { count, diff: shown(diff) };
}

/** Two-decimal values added up, skipping 'n/a'. */
export function sum(values: string[]): string {
  return shown(values.filter((v) => v !== 'n/a').reduce((s, v) => s + hundredths(v), 0n));
}

/** Two-decimal values added up, skipping 'n/a', leaving out the single highest and the single lowest when three
 *  or more are left. */
export function trimmedSum(values: string[]): string {
  const figures = values.filter((v) => v !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return shown(kept.reduce((s, v) => s + v, 0n));
}

/** An amount ("12.34") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim but not bound by a statement). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, and no deferred one. */
export const counts = (c: Claim) => (isOpen(c) || c.status === 'SETTLED') && !c.deferred;

/** Whether a statement binds the claim now: it is stated and not PENDING. */
export const bound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** The claims that count in the live totals (claimed, due-totals, a period's due-total): a person's open (OPEN or
 *  PENDING) claims dated within a hold of theirs, or any once their retirement date is reached on the sheet's today
 *  (yyyy-MM-dd), and not bound by a statement, do not; their other claims still do. */
export function live(claims: Claim[], people: Person[] | undefined, today: string): Claim[] {
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  return claims.filter((c) => {
    const p = byId.get(c.personId);
    return counts(c) && !(isOpen(c) && !bound(c) && p !== undefined && (heldOn(p, c.date) || retiredOn(p, today)));
  });
}

/** The amounts of the claims that count added up, shown with two decimals. */
export function total(claims: Claim[]): string {
  return (claims.filter(counts).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}
import { SheetPage } from '../../slots/defs/sheetPage';
import { isActive } from '../active/active';
import { live, useClaims } from '../claims/claims';
import { STATUSES, useStatusCounts } from '../header/totals';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { personDue, sum, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';
import { useVoidReasons } from '../voidreasons/voidreasons';

/** The sheet's summary, worked out from the same figures the lists show. Per grade: the people on it on the sheet's
 *  today (retired people excluded), their due-totals added up (skipping n/a) and how many of them are active. Per period: its due-total. Per
 *  status: how many of the sheet's claims have it. Per void reason on the sheet's list: how many VOID claims were voided
 *  with it. */
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);

  const active = (people.data ?? []).filter((p) => p.retiredFrom === null);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p, late.today) === grade);
  const gradeDue = (grade: string) =>
    sum(
      onGrade(grade).map((p) =>
        personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor, cap),
      ),
    );
  const withStatus = useStatusCounts(sheetId);
  const voidReasons = useVoidReasons(sheetId);

  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table data-testid="summary-grades">
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`summary-grade-${g}-count`}>{onGrade(g).length}</td>
              <td data-testid={`summary-grade-${g}-due-total`}>{gradeDue(g)}</td>
              <td data-testid={`summary-grade-${g}-active`}>
                {onGrade(g).filter((p) => isActive(p, claims.data, late.today)).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>
                {periodDue(p, claims.data, people.data, rates.data, floor, late)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{withStatus(s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-void-reasons">
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {(voidReasons.data ?? []).map((r) => (
            <tr key={r.reason}>
              <td>{r.reason}</td>
              <td data-testid={`summary-void-${r.reason}-count`}>{r.count}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 40, Component: Summary });

